const {api,waitJob,enter,save,notify,el}=window.gym;
const $=id=>document.getElementById(id);
let state=null,pending=false,finishing=false,recognition=null,listening=false,spokenAt=0,lastPhase='',polling=false;
const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
const launcher=el('section','','interview-launcher');
launcher.innerHTML='<div><p class="eyebrow">45-MINUTE MOCK INTERVIEW</p><h2>Talk through the code with an interviewer.</h2><p>Debug, implement a feature, explain your design. Get hints when you need them and a focused practice plan when you finish.</p></div><button id="chooseInterview" class="primary">Set up an interview ↗</button>';
$('lobby').prepend(launcher);
const startButton=el('button','Start 45-min interview','primary');startButton.id='startInterview';document.querySelector('.work-heading').append(startButton);
const overlay=el('div');overlay.innerHTML=`<dialog id="interviewSetup"><div class="dialog-heading"><h2>Your next interview</h2><button id="closeInterviewSetup" aria-label="Close">×</button></div><label for="interviewLanguage">Language</label><select id="interviewLanguage"><option value="node">JavaScript</option><option value="typescript">TypeScript</option><option value="python">Python</option><option value="java">Java</option><option value="go">Go</option><option value="cpp">C++</option><option value="c">C</option><option value="rust">Rust</option><option value="ruby">Ruby</option><option value="php">PHP</option></select><label for="interviewSource">Codebase</label><select id="interviewSource"><option value="short">Short exercise · JavaScript or Python</option><option value="real">Real historical repository · 9 languages</option></select><p>Imported codebases in any of the 16 runtime languages can also be used: open one, then select Start 45-min interview.</p><p>The timer starts after preparation when you press Start. The interviewer uses a separate local 3B model.</p><button id="prepareInterview" class="primary">Prepare codebase</button><p id="interviewSetupStatus" role="status"></p></dialog>
<section id="interviewerWindow" class="interviewer-window" hidden aria-label="AI interviewer"><div class="interviewer-title"><div><span class="interviewer-avatar">AI</span><strong>Interviewer</strong><small>Local · Qwen Coder 3B</small></div><button id="minimizeInterviewer" aria-label="Minimize interviewer">−</button></div><div class="interview-clock"><strong id="interviewRemaining">45:00</strong><span id="interviewPhase">Understand the problem</span></div><div id="interviewerBody"><div class="interview-controls"><label><input type="checkbox" id="speakReplies" checked> Read replies aloud</label><button id="stopSpeech">Stop voice</button></div><p class="voice-note" id="voiceNote">Voice recognition may use your browser’s online provider. Review the transcript before sending.</p><div id="interviewTranscript" role="log" aria-live="polite"></div><details id="featureAssignment" hidden><summary>Feature acceptance criteria</summary><p id="featureText"></p></details><form id="interviewAnswerForm"><label for="interviewAnswer">Talk through your approach</label><textarea id="interviewAnswer" maxlength="6000" placeholder="Explain your hypothesis, approach, or tradeoff…" required></textarea><div class="interview-actions"><button type="button" id="microphone">🎙 Dictate</button><button class="primary" id="sendInterviewAnswer">Send answer</button></div></form><p id="interviewerStatus" role="status"></p><div class="interview-actions"><button id="interviewHint">I’m stuck · Hint</button><button id="interviewFeature">Feature extension</button></div><div class="interview-actions end-actions"><button id="giveUpInterview">Give up & review</button><button id="finishInterview">Finish & review</button></div></div></section>
<dialog id="interviewFeedback"><div class="dialog-heading"><h2>Your interview review</h2><button id="closeFeedback" aria-label="Close feedback">×</button></div><div id="feedbackContent"></div><div class="interview-actions"><button id="exportFeedback">Download feedback</button><button id="returnPractice" class="primary">Return to free practice</button></div></dialog>`;
document.body.append(overlay);
const download=el('button','Download 3B interviewer');$('pull').after(download);download.onclick=()=>action(download,async()=>{await waitJob(await api('/api/model/pull',{interviewer:true}),text=>$('setupStatus').textContent=text);$('setupStatus').textContent='Interviewer model is ready.';});
async function action(button,fn){const label=button.textContent;button.disabled=true;try{await fn();}catch(error){notify(error.message);}finally{button.disabled=false;button.textContent=button===startButton&&state&&!state.freePractice?(state.status==='ended'?'View interview feedback':'Interview in progress'):label;}}
function stopVoice(){window.speechSynthesis?.cancel();if(recognition&&listening)recognition.stop();}
function speak(text){if(!$('speakReplies').checked||!window.speechSynthesis)return;window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text.replace(/```[\s\S]*?```/g,' Code is shown in the transcript. ').replace(/[*#`]/g,''));utterance.rate=1;utterance.lang='en-US';utterance.onerror=()=>{};window.speechSynthesis.speak(utterance);}
function live(){return state?.status==='active'&&!state.freePractice&&state.deadline>Date.now();}
function lockEditor(){const locked=state&&!state.freePractice&&(state.status!=='active'||state.deadline<=Date.now());$('editor').readOnly=!!locked;$('save').disabled=!!locked;$('run').disabled=!!locked;$('newFile').disabled=!!locked;$('back').disabled=!!(state&&!state.freePractice);}
function render(next,voice=false){state=next;const active=state&&!state.freePractice;$('interviewerWindow').hidden=!active;startButton.textContent=active?(state.status==='ended'?'View interview feedback':'Interview in progress'):'Start 45-min interview';if(!state){lockEditor();return;}$('interviewTranscript').replaceChildren();for(const message of state.transcript){const bubble=el('div','','interview-message '+message.role);bubble.append(el('small',message.role==='assistant'?'INTERVIEWER':'YOU'),el('p',message.content));$('interviewTranscript').append(bubble);}$('interviewTranscript').scrollTop=$('interviewTranscript').scrollHeight;$('featureAssignment').hidden=!state.feature;$('featureText').textContent=state.feature||'';$('interviewFeature').disabled=!!state.feature;$('interviewHint').textContent=`I’m stuck · Hint${state.hints?' ('+state.hints+' used)':''}`;for(const id of ['sendInterviewAnswer','microphone','interviewHint','giveUpInterview','finishInterview'])$(id).disabled=!live()||pending;$('microphone').disabled=!live()||pending||!SpeechRecognition;$('interviewFeature').disabled=!live()||pending||!!state.feature;lockEditor();const last=state.transcript.at(-1);if(voice&&last?.role==='assistant'&&last.at>spokenAt){spokenAt=last.at;speak(last.content);}if(state.status==='ended'&&state.report&&!state.freePractice)showFeedback();}
async function synchronize(){if(!window.gym.current()||polling||pending||finishing)return;polling=true;try{const value=await api('/api/interview?id='+window.gym.current().id);if(value?.id!==state?.id||value?.status!==state?.status)render(value);else if(value)state=value;}catch{}finally{polling=false;}}
window.addEventListener('gym-session',e=>{stopVoice();state=null;spokenAt=0;lastPhase='';render(e.detail.interview||null);synchronize();});
$('chooseInterview').onclick=()=>$('interviewSetup').showModal();$('closeInterviewSetup').onclick=()=>$('interviewSetup').close();
$('interviewLanguage').onchange=()=>{if($('interviewLanguage').value==='python')$('interviewSource').value='short';else if($('interviewLanguage').value!=='node')$('interviewSource').value='real';};
$('prepareInterview').onclick=e=>action(e.currentTarget,async()=>{const language=$('interviewLanguage').value,source=$('interviewSource').value;const status=await api('/api/status');if(!status.interviewerReady)throw new Error('Download the 3B interviewer from Local setup before preparing an interview.');let session;if(source==='short'){if(!['node','python'].includes(language))throw new Error('Choose a real repository for this language, or use JavaScript/Python for a short exercise.');session=await api('/api/session',{challenge:language==='python'?'python-cart':'cart'});}else{if(language==='python')throw new Error('The historical library covers nine non-Python languages. Use the Python exercise or import a Python repository.');const task=await waitJob(await api('/api/task/random',{language,scope:'all'}),text=>$('interviewSetupStatus').textContent=text);session=await waitJob(await api('/api/task/start',{taskId:task.id}),text=>$('interviewSetupStatus').textContent=text);}await enter(session);$('interviewSetup').close();notify('Codebase ready. Press Start 45-min interview when you are ready; the clock has not started.');});
startButton.onclick=e=>action(e.currentTarget,async()=>{if(state&&!state.freePractice){$('interviewerWindow').hidden=false;if(state.report)showFeedback();return;}const status=await api('/api/status');if(!status.interviewerReady)throw new Error('Download the 3B interviewer in Local setup first.');if(!status.docker)throw new Error('Start Docker Desktop before beginning the interview so you can run tests.');startButton.textContent='Preparing environment…';await waitJob(await api('/api/prepare',{id:window.gym.current().id}),text=>{startButton.textContent='Preparing environment…';notify(text);});if(window.gym.isDirty())await save();render(await api('/api/interview/start',{id:window.gym.current().id}),true);});
async function turn(kind,text=''){if(pending||!live())return;pending=true;stopVoice();render(state);$('interviewerStatus').textContent='Thinking…';try{if(window.gym.isDirty())await save();const next=await waitJob(await api('/api/interview/turn',{id:window.gym.current().id,kind,text,path:window.gym.file()}),message=>$('interviewerStatus').textContent=message);pending=false;render(next,true);if(kind==='answer')$('interviewAnswer').value='';}catch(error){notify(error.message);}finally{pending=false;$('interviewerStatus').textContent='';if(state)render(state);}}
$('interviewAnswerForm').onsubmit=e=>{e.preventDefault();turn('answer',$('interviewAnswer').value.trim());};$('interviewHint').onclick=()=>turn('hint');$('interviewFeature').onclick=()=>turn('feature');
async function finish(reason){if(finishing||!state||state.report)return;finishing=true;stopVoice();$('interviewerStatus').textContent='Preparing your feedback…';try{if(reason!=='time_up'&&window.gym.isDirty())await save();const next=await waitJob(await api('/api/interview/end',{id:window.gym.current().id,path:window.gym.file(),reason}),message=>$('interviewerStatus').textContent=message);render(next);}catch(error){notify(error.message);}finally{finishing=false;$('interviewerStatus').textContent='';}}
$('giveUpInterview').onclick=()=>finish('give_up');$('finishInterview').onclick=()=>finish('completed');
function showFeedback(){if(!state?.report)return;stopVoice();const report=state.report,node=$('feedbackContent');node.replaceChildren(el('p',report.summary));const observed=report.observed;node.append(el('p',`${observed.minutesUsed} min · ${observed.testRuns} test runs · ${observed.hints} hints · ${observed.filesEdited.length} files edited`,'feedback-metrics'));if(report.generationError)node.append(el('p','AI review unavailable: '+report.generationError,'voice-note'));for(const row of report.rubric){const card=el('article','','rubric-row');card.append(el('h3',row.area),el('span',row.assessment),el('p',row.evidence));node.append(card);}for(const [title,items]of [['What went well',report.strengths],['What to work on',report.improvements],['Your next practice sessions',report.practicePlan]]){node.append(el('h3',title));const list=el('ul');for(const item of items)list.append(el('li',item));if(!items.length)list.append(el('li','Not enough evidence to assess.'));node.append(list);}node.append(el('p','AI-generated practice feedback. This is not a hiring decision or a validated assessment.','voice-note'));if(!$('interviewFeedback').open)$('interviewFeedback').showModal();}
$('closeFeedback').onclick=()=>$('interviewFeedback').close();$('returnPractice').onclick=e=>action(e.currentTarget,async()=>{render(await api('/api/interview/practice',{id:window.gym.current().id}));$('interviewFeedback').close();$('interviewerWindow').hidden=true;});
$('exportFeedback').onclick=()=>{const blob=new Blob([JSON.stringify({title:state.title,report:state.report,transcript:state.transcript},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='debug-gym-interview-feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('minimizeInterviewer').onclick=()=>{$('interviewerBody').hidden=!$('interviewerBody').hidden;$('minimizeInterviewer').textContent=$('interviewerBody').hidden?'+':'−';};$('stopSpeech').onclick=stopVoice;$('speakReplies').onchange=()=>{if(!$('speakReplies').checked)stopVoice();};
if(!SpeechRecognition){$('microphone').disabled=true;$('voiceNote').textContent='Speech recognition is unavailable in this browser. Type your answers, or open this local app in a browser with speech recognition support.';}else{recognition=new SpeechRecognition();recognition.lang='en-US';recognition.interimResults=true;recognition.continuous=false;let before='';recognition.onstart=()=>{listening=true;$('microphone').textContent='Stop recording';};recognition.onresult=event=>{let text='';for(let i=0;i<event.results.length;i++)text+=event.results[i][0].transcript+' ';$('interviewAnswer').value=(before+' '+text).trim().slice(0,6000);};recognition.onend=()=>{listening=false;$('microphone').textContent='🎙 Dictate';};recognition.onerror=event=>{notify(event.error==='not-allowed'?'Microphone access was denied. You can type your answer instead.':'Voice recognition failed: '+event.error+'. You can type your answer.');};$('microphone').onclick=()=>{if(listening){recognition.stop();return;}if(!live())return;window.speechSynthesis?.cancel();before=$('interviewAnswer').value;try{recognition.start();}catch(error){notify(error.message);}};}
setInterval(()=>{if(!state||state.freePractice)return;const ms=Math.max(0,state.deadline-Date.now()),seconds=Math.ceil(ms/1000);$('interviewRemaining').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;const minutes=(Date.now()-state.started)/60000;const phase=minutes<5?'Understand the problem':minutes<22?'Debug and verify':minutes<35?'Implement a small feature':minutes<42?'Low-level design review':'Explain and reflect';$('interviewPhase').textContent=state.status==='ended'?'Interview complete':phase;if(!lastPhase)lastPhase=phase;if(state.status==='active'&&ms===0&&!finishing){lockEditor();finish('time_up');}else if(live()&&phase!==lastPhase&&!pending&&!finishing){lastPhase=phase;turn('phase');}},1000);
setInterval(synchronize,15000);window.addEventListener('pagehide',stopVoice);synchronize();
